mapper.select:
select snapshot_id, stat_date, region_code, dispatch_company_count, employer_count, dispatched_worker_count, high_risk_enterprise_count, insurance_rate, aq_insurance_rate, today_warning_count, expand_completion_rate, new_injury_rate, online_device_count, pending_warning_count, overdue_injury_count, source_mode, remark from t_cockpit_snapshot where region_code = #{regionCode}
and stat_date <= #{statDate}
order by stat_date desc limit 1

select w.source_module as dimension_code, count(1) as metric_count from t_warning w where date_format(w.create_time, '%Y-%m') = #{statMonth}
and w.region_code like concat(#{regionPrefix}, '%')
group by w.source_module order by metric_count desc, w.source_module asc
